// @Retryable: retries on transient failures with exponential backoff
package com.bank.dividend.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Recover;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service
@Slf4j
public class ExternalPayoutService {

    // Retry 3 times with exponential backoff (1s, 2s, 4s) on connection errors
    @Retryable(
        retryFor = RuntimeException.class,
        maxAttempts = 3,
        backoff = @Backoff(delay = 1000, multiplier = 2))
    public void processPayout(String accountId, BigDecimal amount) {
        log.info("Calling external payout API: {} Rs.{}", accountId, amount);

        // Simulate transient failure (30% chance)
        if (Math.random() < 0.3) {
            throw new RuntimeException("Payout API temporarily unavailable");
        }

        log.info("Payout successful: {} Rs.{}", accountId, amount);
    }

    // Fallback after all retries exhausted
    @Recover
    public void payoutFallback(RuntimeException e, String accountId, BigDecimal amount) {
        log.error("Payout FAILED after 3 retries for {} Rs.{}: {}",
            accountId, amount, e.getMessage());
        // Queue for manual processing or DLQ
    }
}
