// @Value: inject properties. SpEL: dynamic expressions.
package com.bank.dividend.service;

import com.bank.dividend.model.DividendRecord;
import com.bank.dividend.repository.DividendRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class DividendService {

    private final DividendRepository dividendRepo;
    private final ExternalPayoutService payoutService;

    // @Value: inject from application.yml
    @Value("${dividend.tax-rate:0.10}")
    private BigDecimal taxRate;

    @Value("${dividend.min-payout:100}")
    private BigDecimal minPayout;

    // SpEL: dynamic expression
    @Value("#{T(java.time.LocalDate).now().getYear()}")
    private int currentYear;

    @Value("${app.instance-id}")
    private String instanceId;

    @Transactional
    public int processDeclaredDividends() {
        List<DividendRecord> declared = dividendRepo.findByStatus("DECLARED");
        log.info("Processing {} declared dividends (tax={}%, minPayout={}, year={}, instance={})",
            declared.size(), taxRate.multiply(new BigDecimal("100")), minPayout, currentYear, instanceId);

        int processed = 0;
        for (DividendRecord div : declared) {
            if (div.getTotalAmount().compareTo(minPayout) < 0) {
                log.info("Skipping {} — amount {} below minimum {}", div.getDividendId(), div.getTotalAmount(), minPayout);
                continue;
            }

            BigDecimal tax = div.getTotalAmount().multiply(taxRate).setScale(2, RoundingMode.HALF_UP);
            BigDecimal netAmount = div.getTotalAmount().subtract(tax);

            div.markProcessing();
            try {
                payoutService.processPayout(div.getAccountId(), netAmount);
                div.markPaidOut();
                processed++;
            } catch (Exception e) {
                div.markFailed(e.getMessage());
            }
            dividendRepo.save(div);
        }
        return processed;
    }

    public List<DividendRecord> getByAccount(String accountId) {
        return dividendRepo.findByAccountId(accountId);
    }
}
