// CommandLineRunner: runs AFTER context is ready, BEFORE serving traffic
package com.bank.dividend.runner;

import com.bank.dividend.repository.DividendRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.CommandLineRunner;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

@Component
@Order(1)  // runs before other runners with higher order
@RequiredArgsConstructor
@Slf4j
public class StartupValidator implements CommandLineRunner {

    private final DividendRepository dividendRepo;

    @Override
    public void run(String... args) {
        // ApplicationRunner receives parsed ApplicationArguments instead of raw String[]
        // CommandLineRunner receives raw String[] — simpler
        long count = dividendRepo.count();
        log.info("[STARTUP] CommandLineRunner: {} dividend records in database", count);
        log.info("[STARTUP] Flyway migrations applied. DB schema is valid.");
        log.info("[STARTUP] Ready to serve requests.");
    }
}
